Item.method_code:
const { data, on_click_handler: clickHandler } = options.currentTarget;
const { favoriteLayout } = options.getState();
const gridLayoutFavorites = options.getProps().favorites;
const { favorites } = aras.getMainWindow();
const roots = [...target.children];
roots.forEach((itemName) => {
	data.get(itemName).checked = itemName === favoriteLayout;
});

const previousRoots = target.roots || [];
const customLayouts = previousRoots.filter((itemName) => !roots.includes(itemName));
customLayouts.forEach((itemName) => {
	data.delete(itemName);
});

const { convertLayoutToStateFormat, filterFavorites } = favorites;

const favoriteLayouts = filterFavorites(gridLayoutFavorites, 'Grid Layout');
const noLabelString = aras.getResource('', 'common.no_label');
const layoutList = [];
const { itemType, relatedItemType } = options;
favoriteLayouts.forEach((value) => {
	const layoutObject = {
		label: noLabelString,
		...value,
		settings: convertLayoutToStateFormat(value['additional_data'], { itemType, relatedItemType }, options.location),
		on_click_handler: clickHandler,
		group_id: 'layouts',
		name: value.id,
		checked: value.id === favoriteLayout
	};

	delete layoutObject['additional_data'];
	layoutList.push(value.id);
	data.set(value.id, layoutObject);
});

const currentLocale = aras.getIomSessionContext().GetLanguageCode();
layoutList.sort((columnName1, columnName2) => {
	const label1 = data.get(columnName1).label;
	const label2 = data.get(columnName2).label;

	return label1.localeCompare(label2, currentLocale, {
		sensitivity: 'base'
	});
});
if (
	customLayouts.length > favoriteLayouts.length &&
	!favoriteLayout.startsWith('searchview.commandbar.layouts') &&
	!gridLayoutFavorites[favoriteLayout]
) {
	const { setCurrentLayout } = options.getActions();
	setCurrentLayout('searchview.commandbar.layouts.default');
}

return {
	roots: roots.concat(layoutList)
};
